import { useEffect, useId, useRef, useState } from 'react';

type Command = { id: string; group: string; title: string; terms: string; value: string };
const commands: Command[] = [
  {
    "id": "solo",
    "group": "Live answers",
    "title": "Who built the IT platform?",
    "terms": "solo ownership system it architecture",
    "value": "SYS-01 was designed and built end to end by one developer. Its architecture was verified before fleet rollout."
  },
  {
    "id": "ratio",
    "group": "Live answers",
    "title": "How is the KPI ratio calculated?",
    "terms": "kpi pooled ratio sites denominator",
    "value": "Add the reporting sites’ numerators and divide by the sum of their denominators. Count missing denominators separately."
  },
  {
    "id": "cv",
    "group": "Pages",
    "title": "Interactive CV",
    "terms": "cv pdf germany relocation",
    "value": "/cv/"
  },
  {
    "id": "systems",
    "group": "Pages",
    "title": "System comparison",
    "terms": "systems architecture platforms",
    "value": "/systems/"
  },
  {
    "id": "vault",
    "group": "Pages",
    "title": "Component vault",
    "terms": "components vault patterns",
    "value": "/vault/"
  },
  {
    "id": "rtl",
    "group": "Quick actions",
    "title": "Set right-to-left",
    "terms": "rtl right to left direction",
    "value": "rtl"
  },
  {
    "id": "ltr",
    "group": "Quick actions",
    "title": "Set left-to-right",
    "terms": "ltr left to right direction",
    "value": "ltr"
  }
];
const groups = ["Live answers","Pages","Quick actions"];
function findCommands(raw: string, rows: Command[]) {
  const words = raw.toLowerCase().replace(/[^a-z0-9 -]/g, ' ').split(/[ -]+/).filter(Boolean);
  const intents: Record<string, string> = { open: 'Pages', go: 'Pages', page: 'Pages', set: 'Quick actions', switch: 'Quick actions', action: 'Quick actions', who: 'Live answers', what: 'Live answers', how: 'Live answers', answer: 'Live answers' };
  const intent = words.find(word => Object.hasOwn(intents, word));
  const terms = words.filter(word => !Object.hasOwn(intents,word) && !['the','to','is','a','me'].includes(word));
  return rows.filter(row => (!intent || row.group === intents[intent]) && terms.every(term => (row.title + ' ' + row.terms).toLowerCase().includes(term)));
}

export default function CommandAskBar() {
  const uid = useId();
  const dialog = useRef<HTMLDialogElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);
  const [message, setMessage] = useState('');
  const [direction, setDirection] = useState<string>();
  const matches = findCommands(query, commands);
  const activeId = matches[active]?.id;
  function toggle() {
    if (dialog.current?.open) { dialog.current.close(); return; }
    setQuery(''); setActive(0);
    dialog.current?.showModal();
    input.current?.focus();
  }
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); toggle(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);
  useEffect(() => {
    if (dialog.current?.open && activeId) document.getElementById(uid + activeId)?.scrollIntoView({ block: 'nearest' });
  }, [activeId,uid]);
  function choose(row?: Command) {
    if (!row) return;
    if (row.group === 'Pages') { window.location.assign(row.value); return; }
    if (row.group === 'Quick actions') { setDirection(row.value); setMessage('Reading direction: ' + row.value.toUpperCase()); }
    else setMessage(row.value);
    dialog.current?.close();
  }
  return <section dir={direction} className="grid gap-3 text-start [&_button]:rounded-sm [&_button]:border [&_button]:border-[var(--border-strong)] [&_button]:px-2 [&_button]:py-1 [&_button:disabled]:opacity-50 [&_button[aria-pressed=true]]:bg-[var(--accent-tint)] [&_select]:rounded-sm [&_select]:border [&_input:not([type=checkbox])]:border [&_textarea]:border [&_dialog]:bg-[var(--bg-surface)] [&_dialog]:text-[var(--ink-primary)]">
    <button ref={trigger} type="button" aria-haspopup="dialog" onClick={toggle}>Open command bar <kbd>Ctrl K</kbd></button>
    <p role="status">{message}</p>
    <dialog ref={dialog} aria-label="Command bar" className="max-w-full rounded-sm border p-3"
      onClose={() => trigger.current?.focus()} onClick={e => { if (e.target === e.currentTarget) dialog.current?.close(); }}>
      <div className="grid gap-2"><label className="grid">Search commands
        <input ref={input} role="combobox" aria-expanded="true" aria-controls={uid + 'results'} autoComplete="off"
          aria-activedescendant={activeId ? uid + activeId : undefined} value={query}
          onChange={e => { setQuery(e.target.value); setActive(0); }} onKeyDown={e => {
            if (e.key === 'Enter') { e.preventDefault(); choose(matches[active]); }
            if (['ArrowDown','ArrowUp'].includes(e.key)) {
              e.preventDefault();
              if (matches.length) setActive((active + (e.key === 'ArrowDown' ? 1 : -1) + matches.length) % matches.length);
            }
          }} />
      </label>
      <div id={uid + 'results'} role="listbox" aria-label="Matching commands" className="max-h-72 overflow-auto">{groups.map(group => {
        const entries = matches.filter(row => row.group === group);
        return entries.length > 0 && <div key={group} role="group" aria-label={group}><h3 className="pt-2 text-xs font-semibold">{group}</h3>
          {entries.map(row => <button key={row.id} id={uid + row.id} type="button" role="option" tabIndex={-1}
            aria-selected={activeId === row.id} className={'block w-full border-s-2 p-1 text-start ' + (activeId === row.id ? 'font-bold underline' : '')}
            onMouseMove={() => setActive(matches.findIndex(r => r.id === row.id))} onClick={() => choose(row)}>{row.title}</button>)}</div>;
      })}</div>
      {!matches.length && <p>No matching commands.</p>}<button type="button" onClick={() => dialog.current?.close()}>Close</button></div>
    </dialog>
  </section>;
}
